cd /app && python3 -c "
import numpy as np
rows=[]
for line in open('graphene.dat'):
    line=line.strip()
    if not line: continue
    a,b=line.split('\t'); rows.append((float(a.replace(',','.')),float(b.replace(',','.'))))
d=np.array(rows); x=d[:,0]; y=d[:,1]
idx=np.argsort(x); x=x[idx]; y=y[idx]
for lo,hi,step in [(0,2000,50),(2000,5000,50),(5000,8000,50),(8000,12000,100),(12000,20000,100),(20000,47184,200)]:
    print('---',lo,hi)
    for i in range(len(x)):
        if lo<=x[i]<hi and (i==0 or x[i]-x[i-1]>=0):
            pass
    # sample by nearest index
    for xv in np.arange(lo,hi,step):
        j=np.searchsorted(x,xv)
        if j<len(x): print(f'{x[j]:.1f} {y[j]:.1f}')
" > samples.txt; head -100 samples.txt
